import {imageGeometry,reanchorAsset} from './runtime.mjs';
import {MAP_PROP_KINDS} from './prop-library.mjs';
export function mountObjectGrounding(h){
 const $=id=>document.getElementById(id),controls=document.createElement('div');controls.innerHTML=`<h3>Loại vật thể & chạm đất</h3><label>Loại ảnh<select id="objectKind"><option value="custom">Vật thể riêng</option><option value="tree">Cây / vật che cao</option><option value="rock">Đá</option><option value="bush">Bụi cây</option><option value="low">Trang trí thấp</option><option value="bridge">Cầu</option></select></label><label><input id="objectFade" type="checkbox"> Mờ khi che nhân vật</label><label><input id="objectShadow" type="checkbox"> Bóng chạm đất</label><label>Sắp trước/sau và bóng theo<select id="objectGrounding"><option value="image">Gốc phần ảnh có nét vẽ · bỏ qua viền trong suốt</option><option value="anchor">Điểm neo đã đặt thủ công</option></select></label><button id="autoGround">◎ Đặt neo về gốc ảnh · giữ nguyên hình</button><p class="hint">Dùng chung cho mọi bản sao của ảnh này. Không cắt ảnh hoặc đổi kích thước. Đặt neo tự động giữ nguyên vị trí hình và vùng cản đã có; có thể Hoàn tác. Nếu gốc nằm ngoài map, hãy kéo cây vào trong trước.</p>`;
 $('objectFields').prepend(controls);$('objectKind').replaceChildren(...Object.entries(MAP_PROP_KINDS).filter(([id])=>id!=='ground').map(([id,name])=>new Option(name,id)));for(const id of ['tree','house','tall','fence','post','low','rock'])$('uploadKind').add(new Option(MAP_PROP_KINDS[id],id));
 const on=(id,fn)=>$(id).addEventListener('change',h.safe(fn)),get=()=>{const o=h.selected();return o?h.state.project.assets[o.asset]:null};
 function refresh(){const s=get();if(!s)return;$('objectKind').value=s.kind;$('objectFade').checked=s.fadeBehind??(s.kind==='tree'||s.kind==='custom');$('objectShadow').checked=s.groundShadow??!!s.user;$('objectGrounding').value=s.grounding??(s.user?'image':'anchor')}
 for(const [id,key]of [['objectKind','kind'],['objectGrounding','grounding'],['objectFade','fadeBehind'],['objectShadow','groundShadow']])on(id,()=>h.update(p=>p.assets[h.selected().asset][key]=$(id).type==='checkbox'?$(id).checked:$(id).value));
 $('autoGround').addEventListener('click',h.safe(async()=>{const o=h.selected();if(!o)return;const id=o.asset,src=get().src,g=imageGeometry(await h.image(src));if(h.selected()?.asset!==id||h.state.project.assets[id]?.src!==src)throw Error('Lựa chọn đã thay đổi; chọn lại ảnh cần đặt neo.');if(!g)throw Error('Không đọc được vùng ảnh có nét vẽ. Dùng ảnh PNG/WebP trong suốt hoặc chỉnh neo thủ công.');h.update(p=>Object.assign(p,reanchorAsset(p,id,g.foot.x,g.foot.y)));h.message('Đã đặt neo về gốc ảnh, giữ nguyên kích thước/hình ảnh/vùng cản của mọi bản sao. Có thể Hoàn tác.')}));
 return {refresh};
}
